#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_TOKEN_LEN 256
#define HMAC_LEN 32
#define HEADER_SIZE 8
#define MAX_PAYLOAD 4096

typedef struct {
    uint16_t version;
    uint16_t token_length;
    uint16_t payload_length;
    uint16_t flags;
} __attribute__((packed)) packet_header_t;

typedef struct {
    char username[64];
    uint8_t token[MAX_TOKEN_LEN];
    int token_len;
    int authenticated;
    int privilege_level;
} session_t;

static uint8_t server_secret[32] = {
    0x41, 0x7a, 0x3c, 0x9f, 0x12, 0xde, 0x88, 0x45,
    0x6b, 0x2e, 0xf1, 0x09, 0xcd, 0x73, 0xa4, 0x56,
    0x89, 0x1b, 0xe7, 0x34, 0x5a, 0xc8, 0x0f, 0x92,
    0xd6, 0x4e, 0xb3, 0x67, 0x1c, 0xa0, 0x58, 0xf4
};

static uint8_t admin_token[32] = {
    0xde, 0xad, 0xbe, 0xef, 0xca, 0xfe, 0xba, 0xbe,
    0x13, 0x37, 0x42, 0x42, 0xfe, 0xed, 0xfa, 0xce,
    0xaa, 0xbb, 0xcc, 0xdd, 0xee, 0xff, 0x00, 0x11,
    0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88, 0x99
};

/* Compute simple HMAC for demonstration */
static void compute_hmac(const uint8_t *data, size_t data_len,
                         const uint8_t *key, size_t key_len,
                         uint8_t *out) {
    uint8_t ipad[64], opad[64];
    memset(ipad, 0x36, 64);
    memset(opad, 0x5c, 64);
    for (size_t i = 0; i < key_len && i < 64; i++) {
        ipad[i] ^= key[i];
        opad[i] ^= key[i];
    }
    /* Simplified: XOR-based MAC for demo purposes */
    uint8_t inner[32];
    memset(inner, 0, 32);
    for (size_t i = 0; i < data_len; i++) {
        inner[i % 32] ^= data[i] ^ ipad[i % 64];
    }
    memset(out, 0, 32);
    for (int i = 0; i < 32; i++) {
        out[i] = inner[i] ^ opad[i % 64];
    }
}

/* Validate token length from packet header */
static int validate_token_field(const packet_header_t *hdr) {
    /* Ensure token_length is within acceptable bounds */
    if (hdr->token_length > MAX_TOKEN_LEN) {
        return -1;
    }
    if (hdr->token_length == 0) {
        return -1;
    }
    return 0;
}

/* Compare tokens using constant-time comparison */
static int secure_compare(const uint8_t *a, const uint8_t *b, size_t len) {
    volatile uint8_t result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0 ? 1 : 0;
}

/* Authenticate session based on received token */
static int authenticate_session(session_t *session, const uint8_t *recv_token,
                                uint16_t token_len) {
    uint8_t expected_hmac[HMAC_LEN];

    /* Bounds check token_len before any use */
    if (token_len == 0 || token_len > MAX_TOKEN_LEN) {
        return -1;
    }

    /* Check for admin token (fixed-length comparison) */
    if (token_len == HMAC_LEN) {
        if (secure_compare(recv_token, admin_token, HMAC_LEN)) {
            session->authenticated = 1;
            session->privilege_level = 9;
            memcpy(session->token, recv_token, token_len);
            session->token_len = (int)token_len;
            return 0;
        }
    }

    /* Compute expected HMAC from username */
    compute_hmac((const uint8_t *)session->username,
                 strlen(session->username),
                 server_secret, sizeof(server_secret),
                 expected_hmac);

    if (token_len >= HMAC_LEN) {
        if (secure_compare(recv_token, expected_hmac, HMAC_LEN)) {
            session->authenticated = 1;
            session->privilege_level = 1;
            memcpy(session->token, recv_token, token_len);
            session->token_len = (int)token_len;
            return 0;
        }
    }

    return -1;
}

/* Process authentication packet */
static int process_auth_packet(int client_fd, session_t *session) {
    uint8_t buffer[MAX_PAYLOAD];
    ssize_t bytes_read;

    bytes_read = read(client_fd, buffer, sizeof(buffer));
    if (bytes_read < HEADER_SIZE) {
        return -1;
    }

    packet_header_t *hdr = (packet_header_t *)buffer;

    /* Version check */
    if (hdr->version != 0x0102) {
        return -1;
    }

    /* Validate token length field */
    if (validate_token_field(hdr) != 0) {
        return -1;
    }

    /* Ensure we received enough data */
    size_t expected_size = HEADER_SIZE + (size_t)hdr->token_length;
    if ((size_t)bytes_read < expected_size) {
        return -1;
    }

    /* Extract username from flags (simplified: use predefined) */
    if (hdr->flags & 0x01) {
        strncpy(session->username, "admin", sizeof(session->username) - 1);
        session->username[sizeof(session->username) - 1] = '\0';
    } else {
        strncpy(session->username, "user", sizeof(session->username) - 1);
        session->username[sizeof(session->username) - 1] = '\0';
    }

    /* Authenticate with the received token */
    uint8_t *token_data = buffer + HEADER_SIZE;
    int result = authenticate_session(session, token_data, hdr->token_length);

    return result;
}

/* Handle authorized commands */
static void handle_command(int client_fd, session_t *session) {
    uint8_t cmd_buf[512];
    ssize_t n = read(client_fd, cmd_buf, sizeof(cmd_buf) - 1);
    if (n <= 0) return;
    cmd_buf[n] = '\0';

    if (!session->authenticated) {
        const char *msg = "ERROR: Not authenticated\n";
        write(client_fd, msg, strlen(msg));
        return;
    }

    if (strncmp((char *)cmd_buf, "GET_STATUS", 10) == 0) {
        char resp[256];
        int len = snprintf(resp, sizeof(resp),
                          "OK: user=%s level=%d\n",
                          session->username, session->privilege_level);
        if (len > 0 && (size_t)len < sizeof(resp)) {
            write(client_fd, resp, len);
        }
    } else if (strncmp((char *)cmd_buf, "ADMIN_EXEC", 10) == 0) {
        if (session->privilege_level >= 5) {
            const char *msg = "OK: Admin command executed\n";
            write(client_fd, msg, strlen(msg));
        } else {
            const char *msg = "ERROR: Insufficient privileges\n";
            write(client_fd, msg, strlen(msg));
        }
    }
}

int main(int argc, char *argv[]) {
    int server_fd, client_fd;
    struct sockaddr_in addr;
    int opt = 1;

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) return 1;

    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = htons(8443);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        close(server_fd);
        return 1;
    }

    if (listen(server_fd, 5) < 0) {
        close(server_fd);
        return 1;
    }

    while (1) {
        client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) continue;

        session_t session;
        memset(&session, 0, sizeof(session));

        if (process_auth_packet(client_fd, &session) == 0) {
            handle_command(client_fd, &session);
        }

        close(client_fd);
    }

    close(server_fd);
    return 0;
}
